// AI-Personalized Pricing Engine
// Dynamically adjusts pricing per visitor based on real-time signals

const pricingCache = new Map();
const DEFAULT_PRICE = 49.99;

function getVisitorPrice(visitorId, sessionData) {
  if (pricingCache.has(visitorId)) {
    return pricingCache.get(visitorId);
  }
  let price = DEFAULT_PRICE;
  // Factor: page views (higher engagement = higher willingness)
  if (sessionData.pageViews > 10) price *= 1.2;
  // Factor: time on site
  if (sessionData.sessionDuration > 300) price *= 1.1;
  // Factor: referrer (organic search = higher intent)
  if (sessionData.referrer && sessionData.referrer.includes('google')) price *= 1.15;
  // Factor: device type (desktop = higher conversion)
  if (sessionData.device === 'desktop') price *= 1.05;
  // Cap price
  price = Math.min(price, 199.99);
  // Round to nearest cent
  price = Math.round(price * 100) / 100;
  pricingCache.set(visitorId, price);
  // Expire cache after 1 hour
  setTimeout(() => pricingCache.delete(visitorId), 3600000);
  return price;
}

module.exports = { getVisitorPrice };
